public ByteVector putInt(final int intValue) {
    final int index = this.length;
    if (this.length + 4 > this.buffer.length) {
      final ByteVector newVec = new ByteVector(this.length + 4);
      System.arraycopy(this.buffer, 0, newVec.buffer, 0, index);
      this.buffer = newVec.buffer;
    }

    this.buffer[index] = (byte) (intValue >>> 24);
    this.buffer[index + 1] = (byte) (intValue >>> 16);
    this.buffer[index + 2] = (byte) (intValue >>> 8);
    this.buffer[index + 3] = (byte) intValue;

    this.length += 4;
    return this;
  }

