private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if the subgraph is complete by checking the degree of each vertex in the induced subgraph
    for (var vertex : vertices) {
        for (var neighbor : graph.getNeighbors(vertex)) {
            if (!vertices.contains(neighbor)) {
                return false;
            }
        }
    }
    return true;
}

public List<Integer> computeLowerBounds(List<K> keys) {
  List<Integer> lowerBounds = new ArrayList<>(keys.size());
  for (K key : keys) {
    int lowerBound = 0;

    for (K otherKey : keys) {
      if (key.compareTo(otherKey) > 0) {
        lowerBound++;
      }
    }

    lowerBounds.add(lowerBound);
  }

  return lowerBounds;
}

private void pop(final String descriptor) {
        int brackets = 0;
        int index = 0;
        while (index < descriptor.length()) {
            switch (descriptor.charAt(index)) {
                case '[':
                    brackets++;
                    break;
                case ']':
                    brackets--;
                    break;
                case '(':
                    if (brackets == 0) {
                        pop(descriptor.substring(index + 1, descriptor.length() - 1));
                        return;
                    }
                    break;
                default:
                    break;
            }
            index++;
        }
    }

