private List<Integer> computeUpperBounds(List<K> keys) {
    Map<K, Integer> upperBounds = new HashMap<>();
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        Integer upperBound = upperBounds.get(key);
        if (upperBound == null) {
            upperBound = 0;
        }
        upperBound += key.hashCode();
        upperBounds.put(key, upperBound);
    }
    return new ArrayList<>(upperBounds.values());
}

public static string EncodeTemplateNames(string s)
{
    string encodedString = "";
    for (int i = 0; i < s.Length; i++)
    {
        if (s[i] == '{')
        {
            encodedString += "%7B";
        }
        else if (s[i] == '}')
