public static String applyRelativePath(String path, String relativePath) {
String[] pathSplit = path.split("/");
String[] relativePathSplit = relativePath.split("/");

int pathLength = pathSplit.length;
int relativePathLength = relativePathSplit.length;

StringBuilder newPath = new StringBuilder();
for (int i = 0; i < pathLength - relativePathLength; i++) {
newPath.append(pathSplit[i]);
if (i < pathLength - 1) {
newPath.append("/");
}
}

for (int i = 0; i < relativePathLength; i++) {
if (!relativePathSplit[i].equals(".")) {
newPath.append(relativePathSplit[i]);
if (i < relativePathLength - 1) {
newPath.append("/");
}
}
}
return newPath.toString();
}

