public Edge edgeToNext() {
	// If the current node is virtual, find its real counterpart
	Node current = this;
	if (current.isVirtual()) {
		current = current.getRealNode();
	}
	// Find the next node and create an edge
	Node next = this.nextNode();
	if (next == null) {
		throw new IllegalStateException("Cannot find next node");
	}
	Edge edge = new Edge(current, next);
	return edge;
}

