public List<ThreadSnapshot> loadThreadSnapshotsInAppointingTimeRange (File file, List < ProfileAnalyzeTimeRange > timeRanges) throws IOException {
    List < ThreadSnapshot > threadSnapshots = new ArrayList <> ();
    BufferedReader br = new BufferedReader (new FileReader (file));
    String str;
    while ((str = br.readLine ()) != null) {
      String [] tokens = str.split ("\\s+", 3); // split on whitespace and store first 3 tokens
      String threadID = tokens [0];
      String snapshotTime = tokens [1];
      String methodName = tokens [2];
      long time = Long.parseLong (snapshotTime);
      if (timeRanges.stream ().filter (t -> t.contains (time)).count () > 0) threadSnapshots.add (new ThreadSnapshot (threadID, time, methodName));
    }
    return threadSnapshots;
  }
